import { Soundtrack, type Cue } from "../shared/Soundtrack";
import { VOICE_CLIPS } from "./captions";
import { FPS, SCENE_STARTS, SHOTS, SIGNAL_LOST } from "./constants";
import narration from "./narration.json";

// Score and SFX are generated by `node scripts/generate-audio.mjs jupiter`
// into public/jupiter/. No whooshes or playful sounds here: the score starts
// calm, turns dangerous when the keys appear, and goes silent when the radio cuts out.

const s = (scene: number, seconds: number) => Math.round(SCENE_STARTS[scene] + seconds * FPS);

// Radio lines get a squelch click at each end and a static bed underneath.
const radioCues: Cue[] = narration.lines
  .filter((l) => l.tone === "radio")
  .flatMap((l) => [
    { at: s(l.scene, l.start) - 3, src: "jupiter/squelch.mp3", volume: 0.5 },
    { at: s(l.scene, l.start) - 2, src: "jupiter/static.mp3", volume: 0.14 },
    ...(l.scene === 3 ? [] : [{ at: s(l.scene, l.start + l.duration), src: "jupiter/squelch.mp3", volume: 0.45 }]),
  ]);

const CUES: Cue[] = [
  ...radioCues,
  { at: s(3, 0), src: "jupiter/alarm.mp3", volume: 0.2 },
  // Static burst, then the long flatline bleep
  { at: s(3, SIGNAL_LOST - 0.38), src: "jupiter/flatline.mp3", volume: 0.5 },
  ...SHOTS.flatMap((shot) => [
    { at: s(4, shot), src: "jupiter/gunshot.mp3", volume: 0.55 },
    { at: s(4, shot + 0.06), src: "jupiter/vanish.mp3", volume: 0.3 },
  ]),
];

export const SoundEffects: React.FC = () => (
  <Soundtrack music="jupiter/score.mp3" voice={VOICE_CLIPS} cues={CUES} musicVolume={0.5} duckedVolume={0.16} />
);
